<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: ['auth', 'admin'] })
const route = useRoute(); const { data, refresh } = await useFetch<any>(`/api/admin/requests/${route.params.id}`)
const note = ref(''); const errorMessage = ref('')
const statusText: Record<string, string> = { SUBMITTED: '新心愿', RESEARCHING: '研究中', REJECTED: '已拒绝', CONVERTED: '已进入试做', PUBLISHED: '已上架' }
const actions: Record<string, { to: string, label: string, class: string }[]> = { SUBMITTED: [{ to: 'RESEARCHING', label: '开始研究', class: 'bg-lemon' }, { to: 'CONVERTED', label: '收入待试做清单', class: 'bg-mint' }, { to: 'REJECTED', label: '这次做不了', class: 'bg-peach' }], RESEARCHING: [{ to: 'CONVERTED', label: '研究完成，收入待试做', class: 'bg-mint' }, { to: 'REJECTED', label: '研究后放弃', class: 'bg-peach' }] }
async function transition(toStatus: string) { try { const result = await $fetch<any>(`/api/admin/requests/${route.params.id}/transition`, { method: 'POST', body: { toStatus, note: note.value } }); if (toStatus === 'CONVERTED') return navigateTo(`/admin/dishes/${result.linkedDishId}`); note.value = ''; await refresh() } catch (error: any) { errorMessage.value = error?.data?.message || '操作失败' } }
</script>

<template><div class="mx-auto max-w-4xl"><NuxtLink to="/admin/requests" class="font-black underline">← 返回心愿池</NuxtLink><div v-if="data?.request" class="mt-6 grid gap-6 lg:grid-cols-[1fr_20rem]"><section class="sticker-card bg-lemon p-6"><div class="flex items-center justify-between"><p class="font-black">来自 {{ data.request.userName }}</p><span class="rounded-full border-2 border-ink bg-white px-3 py-1 text-sm font-black">{{ statusText[data.request.status] }}</span></div><h1 class="mt-5 text-4xl font-black">{{ data.request.name }}</h1><p class="mt-4 whitespace-pre-wrap font-semibold leading-relaxed text-ink/70">{{ data.request.description || '她没有写更多描述，发挥空间拉满。' }}</p><NuxtLink v-if="data.request.linkedDishId" :to="`/admin/dishes/${data.request.linkedDishId}`" class="sticker-button mt-6 inline-flex items-center bg-mint px-5">打开关联菜品 →</NuxtLink><div class="mt-8 border-t-2 border-ink/20 pt-5"><h2 class="font-black">研究轨迹</h2><p v-for="item in data.request.history" :key="item.id" class="mt-2 text-sm font-semibold">{{ statusText[item.toStatus] }}<span v-if="item.note" class="text-ink/55"> · {{ item.note }}</span></p></div></section><aside class="sticker-card h-fit p-5"><h2 class="text-xl font-black">大厨决定</h2><textarea v-model="note" class="form-field mt-4 min-h-28" maxlength="500" placeholder="给她的回复或研究笔记" /><p v-if="errorMessage" class="mt-3 font-bold text-danger">{{ errorMessage }}</p><div class="mt-4 space-y-3"><button v-for="action in actions[data.request.status] || []" :key="action.to" class="sticker-button w-full" :class="action.class" @click="transition(action.to)">{{ action.label }}</button><p v-if="!(actions[data.request.status] || []).length" class="rounded-xl bg-ink/5 p-4 text-center font-bold">这个心愿已经处理完成。</p></div></aside></div></div></template>
